CREATE TABLE IF NOT EXISTS shop_review(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_item_id BIGINT NOT NULL UNIQUE,order_id BIGINT NOT NULL,member_id BIGINT NOT NULL,product_id BIGINT NOT NULL,stars INT NOT NULL,body VARCHAR(1500) NOT NULL,followup VARCHAR(1500) NULL,followup_at DATETIME NULL,followup_until DATETIME NOT NULL,visible BOOLEAN NOT NULL DEFAULT TRUE,moderation_note VARCHAR(500) NULL,reply VARCHAR(1000) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX product_reviews(product_id,visible,created_at));
INSERT IGNORE INTO shop_config(config_key,content) VALUES('reviews','{"reviewDays":30,"followupDays":90}');
